import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Storage","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Storage | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/storage"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Storage | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/storage"}]]},"headers":[],"relativePath":"user-guide/storage.md","filePath":"user-guide/storage.md","lastUpdated":1786668537000}'),n={name:"user-guide/storage.md"};function s(l,t,d,c,i,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h1><p>Workspace content storage for chat attachments, feedback screenshots, and lead imports.</p><h2 id="enable-storage" tabindex="-1">Enable Storage <a class="header-anchor" href="#enable-storage" aria-label="Permalink to &quot;Enable Storage&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong></li><li>Find <strong>Storage</strong> (free) under the Storage category</li><li>Click <strong>Install</strong></li></ol><p>New workspaces start with <strong>0 GB</strong> of content storage until Storage is installed. Workspaces that already had Team Chat when Storage shipped were granted the free module automatically.</p><h2 id="allowance" tabindex="-1">Allowance <a class="header-anchor" href="#allowance" aria-label="Permalink to &quot;Allowance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entitlement</th><th>Total allowance</th></tr></thead><tbody><tr><td>Storage only</td><td><strong>1 GB</strong></td></tr><tr><td>Storage 10 GB pack</td><td><strong>10 GB</strong></td></tr><tr><td>Storage 50 GB pack</td><td><strong>50 GB</strong></td></tr><tr><td>Storage 100 GB pack</td><td><strong>100 GB</strong></td></tr><tr><td>Storage 500 GB pack</td><td><strong>500 GB</strong></td></tr><tr><td>Storage 1000 GB pack</td><td><strong>1000 GB</strong></td></tr></tbody></table><p>Pack size is the <strong>total</strong> workspace allowance (not added on top of the free 1 GB).</p><h2 id="upgrade-change-pack" tabindex="-1">Upgrade / change pack <a class="header-anchor" href="#upgrade-change-pack" aria-label="Permalink to &quot;Upgrade / change pack&quot;">​</a></h2><ol><li>If another pack is already active, open that pack in Marketplace and <strong>Cancel subscription</strong></li><li>Purchase the new pack size</li><li>Gateway product mapping must exist for billable packs (Stripe / Creem) before checkout succeeds</li></ol><h2 id="what-counts" tabindex="-1">What counts <a class="header-anchor" href="#what-counts" aria-label="Permalink to &quot;What counts&quot;">​</a></h2><p><strong>Included in quota</strong></p><ul><li>Team Chat message attachments</li><li>Feedback screenshots / attachments</li><li>Lead import source files (and generated error reports when present)</li></ul><p><strong>Not included</strong></p><ul><li>Workspace / Central branding logos and favicons</li><li>Profile avatars</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><strong>Settings → Storage</strong> shows used bytes, allowance, percent used, and the current pack (or Free 1 GB). Use <strong>Upgrade storage</strong> to open Marketplace.</p><h2 id="when-uploads-fail" tabindex="-1">When uploads fail <a class="header-anchor" href="#when-uploads-fail" aria-label="Permalink to &quot;When uploads fail&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Message</th></tr></thead><tbody><tr><td>Storage not installed</td><td>Install the free Storage module</td></tr><tr><td>Over quota</td><td>Upgrade storage pack or free space</td></tr><tr><td>Another pack already active</td><td>Cancel the current pack first</td></tr></tbody></table>',19)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
